const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define lake locations (approximate centers)
  const dorsoidong = ee.Geometry.Point([89.5, 32.8]);
  const chibzhang = ee.Geometry.Point([88.5, 33.0]);

  // Buffer for regional analysis
  const buffer = 5000; // 5km buffer
  const dorsoidong_region = dorsoidong.buffer(buffer);
  const chibzhang_region = chibzhang.buffer(buffer);

  // Target date: October 12, 1987
  const date_start = '1987-10-10';
  const date_end = '1987-10-14';

  // Landsat 5 TM collection
  const col = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterDate(date_start, date_end);

  const count_total = col.size().getInfo();
  print(`Total Landsat 5 images (Oct 10-14, 1987): ${count_total}`);

  if (count_total === 0) {
    print('No Landsat 5 images found for this date range.');
    print('C1');
    return;
  }

  // Get image for this date
  const img = col.first();

  if (img === null) {
    print('Image is null.');
    print('C1');
    return;
  }

  // Landsat 5 TM bands: B1=Blue, B2=Green, B3=Red
  // Use SR_B1 (Blue) for color comparison
  const blue_band = 'SR_B1';
  const red_band = 'SR_B3';
  const green_band = 'SR_B2';

  // Calculate blue intensity (blue reflectance)
  const dorsoidong_blue = img.select(blue_band)
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: dorsoidong_region,
      scale: 30,
      maxPixels: 1e9
    })
    .get(blue_band)
    .getInfo();

  const chibzhang_blue = img.select(blue_band)
    .reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: chibzhang_region,
      scale: 30,
      maxPixels: 1e9
    })
    .get(blue_band)
    .getInfo();

  // Check pixel counts
  const dorsoidong_count = img.select(blue_band)
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: dorsoidong_region,
      scale: 30,
      maxPixels: 1e9
    })
    .get(blue_band)
    .getInfo();

  const chibzhang_count = img.select(blue_band)
    .reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: chibzhang_region,
      scale: 30,
      maxPixels: 1e9
    })
    .get(blue_band)
    .getInfo();

  print(`Dorsoidong Co - Blue: ${dorsoidong_blue}, Pixels: ${dorsoidong_count}`);
  print(`Chibzhang Co - Blue: ${chibzhang_blue}, Pixels: ${chibzhang_count}`);

  // Validation checks
  if (dorsoidong_count === 0 || chibzhang_count === 0) {
    print('No valid pixels for one or both lakes.');
    print('C2');
    return;
  }

  if (dorsoidong_blue === null || chibzhang_blue === null || 
      isNaN(dorsoidong_blue) || isNaN(chibzhang_blue)) {
    print('Calculation returned invalid value.');
    print('C3');
    return;
  }

  // Compare blue values
  // Higher blue reflectance = lighter blue color
  if (dorsoidong_blue > chibzhang_blue) {
    print(`Dorsoidong Co has lighter blue (${dorsoidong_blue.toFixed(2)} > ${chibzhang_blue.toFixed(2)})`);
    print('A');
  } else {
    print(`Chibzhang Co has lighter blue or equal (${chibzhang_blue.toFixed(2)} >= ${dorsoidong_blue.toFixed(2)})`);
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
